select * from mes_stock
where material_code = #{materialCode} and warehouse_code = #{warehouseCode} and batch_no = #{batchNo}
limit 1

select * from mes_trace
where serial_no = #{keyword} or batch_no = #{keyword}
order by trace_id desc limit 1

select * from mes_quality_issue
where serial_no = #{keyword} or batch_no = #{keyword}
order by issue_id desc
